#include <assert.h>
#include <string.h>
#include "../src/c/sync.h"
int main(void) { SyncQueue q={0}; SyncRecord r={.id=7,.schema_version=1,.rep_count=15,.workout=0,.exercise_ids={0,1,2},.weights={180,180,260},.complete=1}; memset(r.reps,5,15); char json[256]; assert(sync_record_to_json(&r,json,sizeof json)>0); assert(strstr(json,"\"e\":[0,1,2]")&&strstr(json,"\"r\":[5,5,5")); assert(sync_queue_push_result(&q,&r)==SYNC_PUSH_ADDED); assert(sync_queue_push_result(&q,&r)==SYNC_PUSH_IDENTICAL); r.weights[0]++; assert(sync_queue_push_result(&q,&r)==SYNC_PUSH_CONFLICT); r.weights[0]--; assert(q.count==1); assert(sync_queue_ack(&q,7)&&q.count==0); r.workout=1; r.exercise_ids[1]=3; r.exercise_ids[2]=4; r.rep_count=11; assert(sync_record_to_json(&r,json,sizeof json)>0); assert(strstr(json,"\"e\":[0,3,4]")&&strstr(json,"\"c\":1")); char tiny[8]; assert(sync_record_to_json(&r,tiny,sizeof tiny)==0); r.id=UINT32_MAX; r.completed_at=INT32_MAX; r.weights[0]=r.weights[1]=r.weights[2]=UINT16_MAX; memset(r.reps,5,11); int n=sync_record_to_json(&r,json,sizeof json); assert(n>0); char exact[n+1]; assert(sync_record_to_json(&r,exact,sizeof exact)==n); assert(sync_record_to_json(&r,tiny,n)==0); return 0; }
